actions.script:
// the work center, and the equipment and the run or operation when named, as Downtime's reportStop
const checks = [['workCenter', facilityId || '_NA_']]
if (assetId) checks.push(['asset', assetId])
if (workEffortId || operationWorkEffortId)
    checks.push([workEffortId ? 'run' : 'operation', workEffortId || operationWorkEffortId])
for (const [recordType, recordId] of checks) {
    if (ec.message.hasError()) break
    ec.service.sync().name('ironstone.manufacturing.AccessServices.check#Record')
            .parameters({appRoot: appRoot, recordType: recordType, recordId: recordId}).call()
}
let reported = {}
if (!ec.message.hasError())
    reported = ec.service.sync().name('mantle.work.ProductionServices.store#ProductionDowntime').parameters({
        operationKey: operationKey, action: 'open', facilityId: facilityId, assetId: assetId || null,
        workEffortId: workEffortId || null, operationWorkEffortId: operationWorkEffortId || null, reasonCode: reasonCode,
        fromDate: fromDate || null, thruDate: thruDate || null, description: description || null}).call()?.result || {}
const id = reported.productionDowntimeId
const url = id ? '/qapps/Manufacturing/WorkCenters/Downtime?productionDowntimeId=' + encodeURIComponent(id)
        + (reported.suggestMaintenance ? '&_openDialog=MaintenanceDialog' : '') : null
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {productionDowntimeId: id, url: url,
    messageInfos: [{type: 'success', link: url, message: 'Stop ' + id + ' reported'
        + (reported.suggestMaintenance ? '; open it to request maintenance' : '')}]})
